const L=(en,hi)=>preferences.language==='hi'?hi:en;
const clamp=(v,min=0,max=100)=>Math.max(min,Math.min(max,v));
const avg=a=>a.length?a.reduce((s,n)=>s+n,0)/a.length:0;
