const labelP=id=>({spending:L('Spending','खर्च'),borrowing:L('Borrowing','उधारी'),protection:L('Protection','सुरक्षा'),taxes:L('Taxes','कर'),wealth:L('Wealth','संपत्ति')}[id]);
const catName=n=>({Housing:'आवास','Loan EMI':'ऋण किस्त',Groceries:'किराना',Dining:'बाहर खाना',Transport:'यातायात',Shopping:'खरीदारी',Subscriptions:'सदस्यताएँ',Utilities:'बिल',Health:'स्वास्थ्य',Travel:'यात्रा',Income:'आय'}[n]&&preferences.language==='hi'?{Housing:'आवास','Loan EMI':'ऋण किस्त',Groceries:'किराना',Dining:'बाहर खाना',Transport:'यातायात',Shopping:'खरीदारी',Subscriptions:'सदस्यताएँ',Utilities:'बिल',Health:'स्वास्थ्य',Travel:'यात्रा',Income:'आय'}[n]:n);
