Object.assign(HI,{'Fitness':'वित्तीय सेहत','Scenarios':'क्या हो अगर','Money Wrapped':'पैसे की कहानी','Rewards':'रिवॉर्ड्स','Financial fitness':'वित्तीय सेहत','Your personal CFO':'आपका निजी CFO','Why this matters':'यह क्यों ज़रूरी है','Needs attention':'ध्यान दें','Doing well':'अच्छी स्थिति','Not assessed':'जाँच बाकी','View details':'विवरण देखें','Save':'सहेजें','Remove':'हटाएँ','My workspace':'मेरा कार्यक्षेत्र','MY MONEY':'मेरा पैसा','MY SUPPORT':'मेरी सहायता','Learn & explore':'सीखें और समझें','All':'सभी','Bank accounts':'बैंक खाते','Fixed deposits':'सावधि जमा','Mutual funds':'म्यूचुअल फंड','Stocks':'शेयर','Retirement':'सेवानिवृत्ति','Bonds':'बॉन्ड','Gold':'सोना','Loans':'ऋण','Insurance':'बीमा','August':'अगस्त','July':'जुलाई','June':'जून','Personal workspace':'निजी कार्यक्षेत्र','A little clarity?':'कुछ स्पष्टता चाहिए?','Explore the numbers behind your next decision.':'अपने अगले निर्णय के पीछे के आँकड़े समझें।','Ask SAARTHI':'सारथी से पूछें','Set your monthly boundaries':'अपने मासिक बजट तय करें','Goal name':'लक्ष्य का नाम','Monthly contribution (₹)':'मासिक योगदान (₹)','Goal horizon (months)':'लक्ष्य अवधि (महीने)','Make this my priority goal':'इसे मेरा प्राथमिक लक्ष्य बनाएँ','Your question':'आपका प्रश्न','Sample data':'नमूना डेटा'});
