const originalPageContent=pageContent,originalReportBody=reportBody,originalAsk=askReply;
pageContent=function(){extra();return ({fitness,scenarios,wrapped,rewards}[page]||(()=>originalPageContent()))();};
const originalPermissions=consentPermissions,originalConsentReview=consentReview,originalPrivacy=privacy;
consentPermissions=()=>originalPermissions().replace('last 6 months','June–August 2026 sample history');
consentReview=()=>originalConsentReview().replace('6 months','3 sample months');
