insightData=()=>coachData().map(i=>({...i,action:i.id}));
function coachCard(i){return `<article class="coach-card ${i.good?'positive':''}"><div class="between"><span class="symbol">${icon(i.icon)}</span><span class="tag ${i.good?'green':''}">${i.good?L('DOING WELL','अच्छी स्थिति'):labelP(i.pillar)}</span></div><h3>${i.title}</h3><p>${i.text}</p>${button(L('Why this matters','यह क्यों ज़रूरी है')+icon('arrow'),'insight','text-btn',`data-id="${esc(i.id)}"`)}</article>`;}
insightList=function(limit=99){const items=coachData().slice(0,limit);return items.length?items.map(i=>`<div class="insight-item"><span class="symbol">${icon(i.icon)}</span><div><h3>${i.title}</h3><p>${i.text}</p>${button(L('Why this matters','यह क्यों ज़रूरी है'),'insight','text-btn',`data-id="${esc(i.id)}"`)}</div></div>`).join(''):empty(L('Choose sample accounts to reveal relevant insights.','संबंधित जानकारी के लिए नमूना खाते चुनें।'));};
insightDialog=function(id){const i=coachData().find(x=>x.id===id);if(!i)return;modal(i.title,`<span class="tag">${labelP(i.pillar)}</span><p class="lead">${i.text}</p><div class="explain-block"><h3>${L('Why this matters','यह क्यों ज़रूरी है')}</h3><p>${i.why}</p></div><div class="explain-block"><h3>${L('How SAARTHI identified this','सारथी ने कैसे पहचाना')}</h3><p>${i.source}</p></div><div class="dialog-actions">${button(i.next,'detail-nav','btn primary',`data-page="${i.destination}"`)}${button(L('Add to my checklist','मेरी सूची में जोड़ें'),'add-check','btn',`data-id="${esc(i.id)}"`)}</div>`);};
overview=function(){const t=totals(),c=cash(),top=coachData().filter(x=>!x.good).slice(0,3);return `${head(L('YOUR MONEY, TOGETHER','आपका पैसा, एक जगह'),L('Good morning, Arjun.','सुप्रभात, अर्जुन।'),L('Let’s make your money make sense.','आइए, अपने पैसे को बेहतर समझें।'),navTo(icon('download')+' '+L('My report','मेरी रिपोर्ट'),'reports'))}${coverageNotice()}${fitnessHero(true)}<div class="metric-row gap">${stat(L('Visible net wealth','दिखाई देने वाली शुद्ध संपत्ति'),compact(t.net),`${compact(t.assets)} − ${compact(t.debt)}`,'wallet')}${stat(L('Monthly cash-flow balance','मासिक नकदी शेष'),c.available?money(c.surplus):'—',c.complete?L('Before your goal contributions','लक्ष्य योगदान से पहले'):L('Partial or unshared history','अधूरा या साझा न किया इतिहास'),'chart')}${stat(L('Connected accounts','जुड़े खाते'),`${state.selected.length} / ${ACCOUNTS.length}`,L('You choose what we see','आप तय करते हैं क्या साझा हो'),'shield')}</div><div class="section-title"><div><h2>${L('A few things deserve your attention.','कुछ बातों पर ध्यान देना ज़रूरी है।')}</h2><p>${L('Prioritised by urgency, impact and available context.','ज़रूरत, प्रभाव और उपलब्ध जानकारी के आधार पर प्राथमिकता।')}</p></div>${navTo(L('All insights','सभी जानकारियाँ'),'insights','text-btn')}</div><div class="grid3">${top.map(coachCard).join('')||empty(L('No connected data yet. Your privacy choices stay in control.','अभी कोई डेटा जुड़ा नहीं है। साझा करना आपकी पसंद है।'))}</div><div class="grid2 gap"><section class="card"><div class="section-title"><h2>${L('Make room for what matters','ज़रूरी लक्ष्यों के लिए जगह बनाएँ')}</h2>${navTo(L('All goals','सभी लक्ष्य'),'goals','text-btn')}</div>${state.goals.slice(0,3).map(g=>`<div class="goal-mini"><div class="between"><b>${esc(g.name)}</b><strong>${pct(g.saved,g.target)}%</strong></div>${percentBar(g.saved,g.target)}<div class="between"><span>${compact(g.saved)} / ${compact(g.target)}</span>${button(L('Explore','देखें'),'goal','text-btn',`data-id="${g.id}"`)}</div></div>`).join('')}</section><section class="wrapped-teaser"><span class="eyebrow">${L('YOUR MONEY WRAPPED','आपके पैसे की कहानी')}</span><h2>${L('Three months.<br>A story worth knowing.','तीन महीने।<br>एक कहानी जो जाननी चाहिए।')}</h2><div class="teaser-bars" aria-hidden="true">${[44,61,75,55,85,100].map(h=>`<i style="height:${h}%"></i>`).join('')}</div><p>${L('Discover your biggest expenses, patterns and next move.','अपने बड़े खर्च, पैटर्न और अगले कदम को समझें।')}</p>${navTo(L('Unwrap my money','मेरे पैसे की कहानी देखें')+icon('arrow'),'wrapped','btn')}</section></div><div class="callout between wrap gap"><div><h2>${L('A small habit. A real step forward.','छोटी आदत। आगे बढ़ने का कदम।')}</h2><p>${L('Learn, review and build healthy money habits with SAARTHI Points.','सीखें, समीक्षा करें और सारथी पॉइंट्स से अच्छी आदतें बनाएँ।')}</p></div>${navTo(L('Explore rewards','रिवॉर्ड्स देखें'),'rewards')}</div>`;};
function pillarTiles(){return `<div class="pillar-grid">${profilePillars().map(p=>`<button class="pillar-tile" data-action="pillar" data-id="${p.id}"><span class="symbol">${icon(p.icon)}</span><h3>${labelP(p.id)}</h3><strong>${p.score??'—'}<small>${p.score===null?'':' / 100'}</small></strong>${percentBar(p.score||0,100)}<span>${scoreLabel(p.score)}</span>${icon('chevron')}</button>`).join('')}</div>`;}
function fitness(){const f=fitnessValue(),history=['June','July','August'].map(m=>({m,...fitnessValue(m)}));return `${head(L('YOUR FINANCIAL HEALTH CHECK','आपकी वित्तीय सेहत की जाँच'),L('Understand your score.<br>Choose your next step.','अपना स्कोर समझें।<br>अगला कदम चुनें।'),L('A transparent coaching index, not a credit score or an advice rating.','एक पारदर्शी डेमो संकेतक—क्रेडिट स्कोर या सलाह की रेटिंग नहीं।'),button(L('Confirm my profile','मेरी जानकारी की पुष्टि करें'),'health-profile','btn'))}${fitnessHero()}<div class="section-title gap"><h2>${L('Five pillars. One connected picture.','पाँच स्तंभ। एक जुड़ी तस्वीर।')}</h2>${button(L('How the score works','स्कोर कैसे बनता है'),'method','text-btn')}</div>${pillarTiles()}<div class="grid2 gap"><section class="card"><h2>${L('What changed across months?','महीनों में क्या बदला?')}</h2><p class="muted">${L('Comparable model view: only spending varies. Other pillars use the same September snapshot and current profile—not observed historical scores.','तुलनीय मॉडल: सिर्फ़ खर्च बदलता है। अन्य स्तंभ सितंबर की समान जानकारी और वर्तमान प्रोफाइल लेते हैं—ये पुराने वास्तविक स्कोर नहीं हैं।')}</p><div class="history-columns">${history.map(h=>`<div><strong>${h.score??'—'}</strong><div class="history-track"><i style="height:${h.score??0}%"></i></div><span>${tx(h.m)}</span></div>`).join('')}</div><p class="small muted">${L('Changing budgets recalculates all periods using the same current targets. Unknown pillars are excluded, never scored zero.','बजट बदलने पर सभी अवधि वर्तमान लक्ष्यों से दोबारा गिनी जाती हैं। अज्ञात स्तंभ बाहर रहते हैं, शून्य नहीं माने जाते।')}</p></section><section class="card"><h2>${L('Your next best actions','आपके अगले उपयोगी कदम')}</h2>${insightList(3)}</section></div>`;}
function pillarDetail(id){const p=profilePillars().find(x=>x.id===id);if(!p)return;const relevant=coachData().filter(x=>x.pillar===id);modal(labelP(id),`<div class="pillar-detail-hero">${scoreRing(p.score,true)}<div><span class="tag">${scoreLabel(p.score)}</span><h3>${p.desc}</h3></div></div><div class="explain-block"><h3>${L('Behind this score','इस स्कोर के पीछे')}</h3><p>${p.formula}</p></div>${id==='wealth'?portfolioDiagnostics():''}${id==='taxes'?`<p>${L('Regime: ','कर व्यवस्था: ')}${esc(state.health.regime)}. ${L('No eligibility assessment or tax calculation is made. Confirm your facts with a qualified tax professional.','कोई पात्रता या कर गणना नहीं की गई है। विशेषज्ञ से अपने तथ्य जाँचें।')}</p>`:''}${relevant.map(i=>`<div class="insight-item"><div><h3>${i.title}</h3><p>${i.text}</p>${button(L('Why this matters','यह क्यों ज़रूरी है'),'insight','text-btn',`data-id="${esc(i.id)}"`)}</div></div>`).join('')}<div class="dialog-actions">${button(id==='protection'||id==='taxes'?L('Update my profile','मेरी जानकारी बदलें'):L('Explore details','विवरण देखें'),id==='protection'||id==='taxes'?'health-profile':'detail-nav','btn primary',`data-page="${id==='spending'?'spending':id==='wealth'?'investments':'review'}"`)}</div>`);}
function healthProfile(){extra();const h=state.health;modal(L('A little more about your picture','आपकी स्थिति के बारे में थोड़ा और'),`<p class="muted">${L('Sample planning inputs only. Don’t enter personal identifiers. Policy presence does not establish adequate cover.','सिर्फ़ नमूना योजना जानकारी। निजी पहचान न भरें। पॉलिसी की मौजूदगी पर्याप्त कवर साबित नहीं करती।')}</p><form id="health-form"><div class="form-grid"><label class="field">${L('Dependants','आश्रित')}<input name="dependants" type="number" min="0" max="20" value="${h.dependants}" required></label><label class="field">${L('Personal health cover (₹)','निजी स्वास्थ्य कवर (₹)')}<input name="personalHealth" type="number" min="0" max="100000000" value="${h.personalHealth}" required></label><label class="field">${L('Life cover (₹)','जीवन कवर (₹)')}<input name="life" type="number" min="0" max="1000000000" value="${h.life}" required></label><label class="field">${L('Tax regime to review','जाँचने की कर व्यवस्था')}<select name="regime">${[['unknown',L('Not confirmed','पुष्टि नहीं')],['old',L('Old regime','पुरानी व्यवस्था')],['new',L('New regime','नई व्यवस्था')]].map(([id,n])=>`<option value="${id}" ${h.regime===id?'selected':''}>${n}</option>`).join('')}</select></label></div><h3 class="gap">${L('Preparation checklist','तैयारी सूची')}</h3>${[['income',L('Income / salary statement','आय / वेतन विवरण')],['interest',L('Interest and deposit statements','ब्याज और जमा विवरण')],['gains',L('Capital-gains statement','पूँजीगत लाभ विवरण')],['tax',L('Tax credit / information statement','कर क्रेडिट / सूचना विवरण')]].map(([id,n])=>`<label class="checkline"><input type="checkbox" name="docs" value="${id}" ${h.docs.includes(id)?'checked':''}>${n}</label>`).join('')}<label class="checkline"><input type="checkbox" name="confirm" required>${L('I confirm these fictional planning inputs.','मैं इस काल्पनिक योजना जानकारी की पुष्टि करता/करती हूँ।')}</label><button class="btn primary gap" type="submit">${L('Save my profile','मेरी जानकारी सहेजें')}</button></form>`);}
function portfolioDiagnostics(){const stock=assets().filter(a=>a.type==='stocks'),total=sum(stock),top=stock.length?stock.reduce((a,b)=>a.value>b.value?a:b):null;return `<div class="explain-block"><h3>${L('Risk, without the jargon','जोखिम, आसान शब्दों में')}</h3><p>${top?L(`${top.name} is ${pct(top.value,total)}% of your shared direct-stock allocation. This is not your whole-portfolio sector exposure.`,`${top.name} आपके साझा सीधे शेयर आवंटन का ${pct(top.value,total)}% है। यह पूरे पोर्टफोलियो का सेक्टर अनुपात नहीं है।`):L('No direct-stock positions shared.','सीधे शेयर साझा नहीं हैं।')}</p>${stock.map(s=>`<div class="between small"><span>${s.name}</span><b>${pct(s.value,total)}%</b></div>${percentBar(s.value,total)}`).join('')}<p class="small muted">${L('Fund look-through holdings, market-cap splits, expense ratios, overlap and risk preferences are unavailable. SAARTHI does not invent these diagnoses or suggest replacement securities.','फंड की अंदरूनी होल्डिंग्स, मार्केट-कैप, खर्च अनुपात, ओवरलैप और जोखिम पसंद उपलब्ध नहीं हैं। सारथी इनका अनुमान या शेयर बदलने का सुझाव नहीं देता।')}</p></div>`;}
const baseInvestments=investments;
investments=function(){const resume=state.simulations.at(-1);return `${head(L('YOUR WEALTH HUB','आपकी संपत्ति का केंद्र'),L('Every investment.<br>A clearer purpose.','हर निवेश।<br>एक स्पष्ट उद्देश्य।'),L('Explore your mix before making your next decision.','अगला निर्णय लेने से पहले अपना निवेश मिश्रण समझें।'),button(L('Ask SAARTHI','सारथी से पूछें'),'chat','btn primary'))}<div class="route-grid">${Object.entries(TYPES).filter(([id])=>!['loan','insurance','bank'].includes(id)).map(([id,n])=>`<button class="route-card" data-action="asset-route" data-id="${id}">${icon(ACCOUNTS.find(a=>a.type===id).icon)}<b>${tx(n)}</b><span>${compact(sum(assets().filter(a=>a.type===id)))}</span></button>`).join('')}</div>${resume?`<div class="callout between wrap gap"><div><h3>${L('Continue exploring your last scenario','अपने पिछले परिदृश्य को आगे देखें')}</h3><p>${esc(resume.label)}</p></div>${navTo(L('Resume','जारी रखें'),'scenarios')}</div>`:''}<div class="grid2 gap"><section class="card">${portfolioDiagnostics()}</section><section class="card"><h2>${L('Stress-test a possibility','एक संभावना का असर जाँचें')}</h2><p class="muted">${L('What would an equity-market fall mean for the holdings you shared? Explore a transparent, no-trade scenario.','शेयर बाज़ार में गिरावट आपके साझा निवेश पर क्या असर डालेगी? बिना ट्रेड का स्पष्ट परिदृश्य देखें।')}</p>${button(L('Try a market scenario','बाज़ार का परिदृश्य आज़माएँ'),'scenario-preset','btn primary','data-id="market"')}<hr class="separator"><h3>${L('Costs need source documents','लागत के लिए स्रोत दस्तावेज़ चाहिए')}</h3><p class="small muted">${L('Your snapshot has values and cost bases, not fund fee schedules. Ask for the current expense ratios before comparing alternatives.','आपके विवरण में मूल्य और लागत है, फंड शुल्क सूची नहीं। तुलना से पहले वर्तमान खर्च अनुपात प्राप्त करें।')}</p>${navTo(L('Prepare review questions','समीक्षा प्रश्न तैयार करें'),'review','text-btn')}</section></div>${baseInvestments().replace(/^[\s\S]*?(?=<div class="metric-row">)/,'')}`;};
insights=function(){const all=coachData(),top=all.filter(i=>!i.good).slice(0,3);return `${head(L('CLARITY BEFORE ACTION','कार्रवाई से पहले स्पष्टता'),L('Less noise.<br>More useful next steps.','कम उलझन।<br>ज़्यादा उपयोगी अगले कदम।'),L('Short answers first. Tap to understand the why.','पहले छोटा उत्तर। कारण समझने के लिए खोलें।'))}<div class="grid3">${top.map(coachCard).join('')||empty(L('No account-based insights yet.','अभी खाते आधारित जानकारी नहीं है।'))}</div><div class="section-title gap"><h2>${L('Explore your five pillars','अपने पाँच स्तंभ देखें')}</h2></div>${pillarTiles()}<div class="grid2 gap"><section class="card"><h2>${L('Give yourself some credit','अपनी अच्छी आदतों को पहचानें')}</h2>${all.filter(i=>i.good).map(i=>`<div class="insight-item"><span class="symbol green">${icon('check')}</span><div><h3>${i.title}</h3><p>${i.text}</p>${button(L('View details','विवरण देखें'),'insight','text-btn',`data-id="${i.id}"`)}</div></div>`).join('')||`<p class="muted">${L('Share enough information to identify positive patterns.','सकारात्मक पैटर्न पहचानने के लिए पर्याप्त जानकारी साझा करें।')}</p>`}</section><section class="card"><h2>${L('Your next-step checklist','आपके अगले कदमों की सूची')}</h2><p class="small muted">${L('Save actions from any insight. Completion is self-reported; no money moves.','किसी भी जानकारी से कदम सहेजें। पूरा होना आपकी पुष्टि है; पैसा नहीं भेजा जाता।')}</p>${Object.entries(state.checks).map(([id,v])=>`<div class="task-row"><div class="task-body"><h3>${esc(v.title)}</h3></div>${button(v.done?L('Undo','वापस लें'):L('Done','पूरा'),'check-done','btn sm',`data-id="${esc(id)}" aria-pressed="${v.done}"`)}</div>`).join('')||`<p>${L('Open an insight and add it here.','एक जानकारी खोलें और यहाँ जोड़ें।')}</p>`}</section></div>`;};
function budgetsPanel(){return `<section class="card gap"><div class="section-title"><div><h2>${L('Your spending goals','आपके खर्च लक्ष्य')}</h2><p>${L('Create, change or remove a target. No payment restrictions.','लक्ष्य बनाएँ, बदलें या हटाएँ। कोई भुगतान रोक नहीं।')}</p></div>${button(icon('plus')+' '+L('Set target','लक्ष्य बनाएँ'),'target-new','btn')}</div><div class="budget-grid">${[...categories(),...Object.entries(state.customBudgets).map(([name,budget])=>({name,budget,value:0,custom:true}))].filter(x=>Number.isFinite(x.budget)).map(x=>`<article class="budget-card"><div class="between"><b>${esc(catName(x.name))}</b>${button(icon('edit'),'target-edit','icon-btn',`data-id="${esc(x.name)}" aria-label="${L('Edit','बदलें')} ${esc(x.name)}"`)}</div><h3>${money(x.value)} <small>/ ${money(x.budget)}</small></h3>${percentBar(x.value,x.budget,x.value>x.budget?'#ae7027':undefined)}<p class="small">${x.value>x.budget?L(`${money(x.value-x.budget)} over target`,`${money(x.value-x.budget)} लक्ष्य से अधिक`):L(`${money(x.budget-x.value)} remaining`,`${money(x.budget-x.value)} बाकी`)}</p>${x.custom?`<p class="small muted">${L('Planning-only category · no matching imported transactions','सिर्फ़ योजना श्रेणी · मेल खाते आयातित लेन-देन नहीं')}</p>`:''}</article>`).join('')}</div></section>`;}
spending=function(){const c=cash(),cats=categories().filter(x=>x.value).sort((a,b)=>b.value-a.value);return `${head(L('EVERYDAY MONEY','रोज़मर्रा का पैसा'),L('Your spending.<br>With a little perspective.','आपका खर्च।<br>थोड़ी समझ के साथ।'),L('Track your month, spot patterns and set your own boundaries.','महीना देखें, पैटर्न समझें और अपनी सीमाएँ तय करें।'),`<label class="field">${L('Month','महीना')}<select id="month">${['August','July','June'].map(m=>`<option value="${m}" ${month===m?'selected':''}>${tx(m)} 2026</option>`).join('')}</select></label>`)}${coverageNotice()}${!c.available?empty(L('Choose bank accounts and transaction permission to see spending.','खर्च देखने के लिए बैंक खाते और लेन-देन की अनुमति चुनें।')):`<div class="metric-row">${stat(L('Money in','आय'),money(c.income),tx(month)+' 2026','wallet')}${stat(L('Money out','खर्च'),money(c.out),L('Known EMI included','ज्ञात EMI शामिल'),'chart')}${stat(L('Cash-flow balance','नकदी शेष'),money(c.surplus),c.complete?L(`${pct(c.surplus,c.income)}% of income remains`,`${pct(c.surplus,c.income)}% आय बची`):L('Partial accounts only','सिर्फ़ आंशिक खाते'),'target',true)}</div><div class="grid2"><section class="card"><h2>${L('Where your money went','आपका पैसा कहाँ गया')}</h2>${donut(cats.map((x,i)=>({...x,name:catName(x.name),color:COLORS[i%COLORS.length]})),c.out,L('spent','खर्च'))}</section><section class="card"><h2>${L('Your three biggest categories','आपकी तीन सबसे बड़ी श्रेणियाँ')}</h2>${cats.slice(0,3).map((x,i)=>`<div class="rank-row"><span>0${i+1}</span><b>${catName(x.name)}</b><strong>${money(x.value)}</strong></div>`).join('')}<p class="muted gap">${L(`Together, these account for ${pct(cats.slice(0,3).reduce((s,x)=>s+x.value,0),c.out)}% of visible spending.`,`मिलकर ये दिखाई देने वाले खर्च का ${pct(cats.slice(0,3).reduce((s,x)=>s+x.value,0),c.out)}% हैं।`)}</p>${navTo(L('See my money story','मेरे पैसे की कहानी देखें'),'wrapped','text-btn')}</section></div>${budgetsPanel()}<section class="card gap"><div class="section-title"><h2>${L('A closer look at transactions','लेन-देन पर एक नज़र')}</h2>${button(icon('download')+' CSV','export-tx','btn sm')}</div><div class="filter-row"><label class="search-field">${icon('search')}<input id="tx-search" aria-label="${L('Search transactions','लेन-देन खोजें')}" placeholder="${L('Search transactions','लेन-देन खोजें')}" value="${esc(txQuery)}"></label><select id="tx-category" aria-label="${L('Category','श्रेणी')}"><option value="all">${L('All categories','सभी श्रेणियाँ')}</option>${['Income',...CATEGORIES.map(x=>x[0])].map(n=>`<option value="${n}" ${txFilter===n?'selected':''}>${catName(n)}</option>`).join('')}</select></div><div id="transaction-results">${transactionTable()}</div></section>`}`;};
function targetDialog(name=''){const standard=CATEGORIES.some(x=>x[0]===name),value=standard?state.budgets[name]:state.customBudgets[name];modal(name?L('Edit spending target','खर्च लक्ष्य बदलें'):L('Make a spending goal','एक खर्च लक्ष्य बनाएँ'),`<form id="target-form" data-original="${esc(name)}"><label class="field">${L('Category','श्रेणी')}<input name="category" list="budget-categories" maxlength="40" value="${esc(name)}" ${name?'readonly':''} required></label><datalist id="budget-categories">${CATEGORIES.map(([n])=>`<option value="${n}"></option>`).join('')}</datalist><label class="field gap">${L('Monthly target (₹)','मासिक लक्ष्य (₹)')}<input name="amount" type="number" min="0" max="10000000" value="${value??5000}" required></label><p class="small muted">${L('Existing categories use shared transactions. A custom category is a planning target until matching records exist.','मौजूदा श्रेणियाँ साझा लेन-देन उपयोग करती हैं। नई श्रेणी रिकॉर्ड आने तक सिर्फ़ योजना लक्ष्य है।')}</p><p class="validation" id="target-error" role="alert"></p><div class="dialog-actions">${name?button(L('Remove target','लक्ष्य हटाएँ'),'target-remove','btn danger',`data-id="${esc(name)}"`):''}<button class="btn primary" type="submit">${L('Save target','लक्ष्य सहेजें')}</button></div></form>`);}
let scenarioType='expenses',scenarioValue=10000;
const SCENARIOS={expenses:{label:()=>L('Expenses rise','खर्च बढ़े'),icon:'wallet',max:50000,step:1000,value:10000},invest:{label:()=>L('Invest more monthly','मासिक निवेश बढ़ाएँ'),icon:'chart',max:30000,step:1000,value:5000},loan:{label:()=>L('Take on a new EMI','नई EMI लें'),icon:'bank',max:30000,step:1000,value:10000},market:{label:()=>L('Equity markets fall','शेयर बाज़ार गिरे'),icon:'trend',max:50,step:1,value:15},save:{label:()=>L('Reduce monthly spending','मासिक खर्च घटाएँ'),icon:'target',max:30000,step:1000,value:5000},purchase:{label:()=>L('Make a one-off purchase','एक बार की खरीदारी'),icon:'bag',max:300000,step:5000,value:50000},retire:{label:()=>L('Reach a corpus sooner','बचत लक्ष्य जल्दी पाएँ'),icon:'sun',max:50000,step:1000,value:10000}};
function scenarioResult(type,v){const c=cash(),planned=state.goals.reduce((s,g)=>s+g.monthly,0),bank=sum(assets().filter(a=>a.type==='bank')),equity=sum(assets().filter(a=>a.type==='stocks'||['mf1','mf2'].includes(a.id)));if(type==='market')return {available:equity>0,before:totals().net,after:totals().net-equity*v/100,label:L('Visible net wealth','दिखाई देने वाली शुद्ध संपत्ति'),note:L(`${money(equity)} shared direct stocks and equity funds × ${v}% fall = ${money(equity*v/100)} decline. All other assets and debts held flat. Retirement look-through not known.`,`${money(equity)} साझा सीधे शेयर और इक्विटी फंड × ${v}% गिरावट = ${money(equity*v/100)} कमी। अन्य संपत्ति और ऋण स्थिर। रिटायरमेंट निवेश का अंदरूनी विवरण अज्ञात।`)};
 if(type==='purchase')return {available:hasType('bank'),before:bank,after:bank-v,label:L('Visible bank cash','दिखाई देने वाला बैंक नकद'),note:L(`Cash only; earmarks are not released. After purchase: ${((bank-v)/80000).toFixed(1)} months of essential outgo. No borrowing assumed.`,`सिर्फ़ नकद; तय उपयोग की राशि मुक्त नहीं की गई। खरीद के बाद: ${((bank-v)/80000).toFixed(1)} महीने का ज़रूरी खर्च। कोई उधार नहीं माना।`)};
 if(type==='retire'){const goal=state.goals.find(g=>g.id==='home')||state.goals[0];const gap=goal?Math.max(0,goal.target-goal.saved):0;return {available:!!goal&&c.complete,before:goal?.monthly?Math.ceil(gap/goal.monthly):null,after:goal&&(goal.monthly+v)>0?Math.ceil(gap/(goal.monthly+v)):null,unit:'months',label:L('Time to selected goal corpus','चुने लक्ष्य की राशि तक समय'),note:L(`Uses ${goal?.name||'no goal'} as a corpus proxy, not retirement adequacy. Flat monthly contributions, zero returns/inflation. Extra ${money(v)} needs funding; current unallocated surplus is ${money(c.surplus-planned)}.`,`राशि के उदाहरण के लिए ${goal?.name||'कोई लक्ष्य नहीं'}; यह रिटायरमेंट पर्याप्तता नहीं है। स्थिर योगदान, शून्य रिटर्न/महँगाई। अतिरिक्त ${money(v)} के लिए स्रोत चाहिए; अभी खाली शेष ${money(c.surplus-planned)} है।`)};}
 const delta=type==='save'?v:-v;return {available:c.complete,before:c.surplus-planned,after:c.surplus-planned+delta,label:L('Unallocated monthly cash','बिना आवंटन का मासिक नकद'),note:L(`${money(c.income)} income − ${money(c.out)} expenses − ${money(planned)} existing goal contributions ${delta>=0?'+':'−'} ${money(v)} scenario change. ${type==='invest'?'Extra investing reduces cash; it is not an expense or a guaranteed return.':'All other inputs stay constant.'}`,`${money(c.income)} आय − ${money(c.out)} खर्च − ${money(planned)} मौजूदा लक्ष्य योगदान ${delta>=0?'+':'−'} ${money(v)} परिदृश्य बदलाव। ${type==='invest'?'अधिक निवेश नकद घटाता है; यह खर्च या गारंटीकृत रिटर्न नहीं है।':'अन्य जानकारी स्थिर है।'}`)};
}
function scenarioOutput(){const r=scenarioResult(scenarioType,scenarioValue),fmt=n=>n===null?'—':r.unit==='months'?n+' '+L('months','महीने'):money(n);return !r.available?empty(L('More selected data is needed for this scenario.','इस परिदृश्य के लिए अधिक चुना डेटा चाहिए।')):`<h3>${r.label}</h3><div class="scenario-compare"><div><span>${L('TODAY','आज')}</span><strong>${fmt(r.before)}</strong></div><div class="${r.after<0?'negative':''}"><span>${L('WHAT IF','अगर ऐसा हो')}</span><strong>${fmt(r.after)}</strong></div></div><p class="small muted gap">${r.note}</p>${r.after<0?notice(L('This leaves a shortfall. Adjust the amount or revisit existing commitments before considering this plan.','इससे कमी बनती है। योजना से पहले राशि बदलें या मौजूदा योगदान की समीक्षा करें।'),true):''}${button(L('Save this scenario','यह परिदृश्य सहेजें'),'store-simulation','btn primary gap')}`;}
function scenarios(){return `${head(L('EXPLORE, BEFORE YOU ACT','करने से पहले समझें'),L('What if life changes?','अगर जीवन बदल जाए?'),L('Change one input. See the trade-off. Nothing moves automatically.','एक जानकारी बदलें। असर देखें। कुछ भी अपने आप नहीं होता।'))}<div class="scenario-grid">${Object.entries(SCENARIOS).map(([id,x])=>`<button class="scenario-choice ${scenarioType===id?'active':''}" data-action="scenario-preset" data-id="${id}" aria-pressed="${scenarioType===id}">${icon(x.icon)}<span>${x.label()}</span></button>`).join('')}</div><div class="grid2 gap"><section class="card"><span class="eyebrow">${L('YOUR SCENARIO','आपका परिदृश्य')}</span><h2>${SCENARIOS[scenarioType].label()}</h2><label class="field gap">${L('Change amount','बदलाव की राशि')}<output id="whatif-value" class="slider-value">${scenarioType==='market'?scenarioValue+'%':money(scenarioValue)}</output><input id="whatif-range" type="range" min="0" max="${SCENARIOS[scenarioType].max}" step="${SCENARIOS[scenarioType].step}" value="${scenarioValue}" aria-label="${SCENARIOS[scenarioType].label()}"></label><div class="between small muted"><span>0</span><span>${scenarioType==='market'?'50%':money(SCENARIOS[scenarioType].max)}</span></div><p class="small muted gap">${L('Illustrative arithmetic, not a forecast. No rates, tax effects or product offers are assumed.','उदाहरण गणना, भविष्यवाणी नहीं। दरें, कर प्रभाव या उत्पाद ऑफ़र नहीं माने गए।')}</p></section><section class="card" id="whatif-output" aria-live="polite">${scenarioOutput()}</section></div><section class="card gap"><h2>${L('Saved explorations','सहेजे गए परिदृश्य')}</h2>${state.simulations.slice().reverse().map(s=>`<div class="task-row"><span class="symbol">${icon('route')}</span><div class="task-body"><h3>${esc(s.label)}</h3><p>${L('Saved inputs only · reload recalculates from current shared data','सिर्फ़ सहेजी जानकारी · दोबारा खोलने पर वर्तमान डेटा से गणना')}</p></div>${button(L('Open','खोलें'),'load-simulation','btn sm',`data-id="${s.id}"`)}${button(L('Remove','हटाएँ'),'delete-simulation','text-btn',`data-id="${s.id}"`)}</div>`).join('')||`<p class="muted">${L('Your first exploration is waiting above.','अपना पहला परिदृश्य ऊपर आज़माएँ।')}</p>`}</section>`;}
function wrapped(){const list=['June','July','August'].map(m=>({name:m,...monthly(m)}));if(!cash().available)return head('MONEY WRAPPED',L('Your story starts with context.','आपकी कहानी जानकारी से शुरू होती है।'),'')+empty(L('Share transactions to reveal your money story.','पैसे की कहानी के लिए लेन-देन साझा करें।'));const first=list[0],last=list[2],highest=list.reduce((a,b)=>a.out>b.out?a:b),strongest=list.reduce((a,b)=>(a.surplus/(a.income||1))>(b.surplus/(b.income||1))?a:b),change=last.out-first.out,subs=last.tx.filter(t=>t.category==='Subscriptions'),top=categories('August').sort((a,b)=>b.value-a.value).slice(0,3);return `${head(L('JUNE — AUGUST 2026','जून — अगस्त 2026'),L('Your money has a story.','आपके पैसे की एक कहानी है।'),L('Three sample months. The patterns behind your everyday choices.','तीन नमूना महीने। आपके रोज़मर्रा के चुनावों के पीछे के पैटर्न।'),navTo(L('Full report','पूरी रिपोर्ट'),'reports'))}${coverageNotice()}<div class="story-grid"><article class="story-card blush"><span>01 / ${L('YOUR BIGGEST CATEGORY','आपकी सबसे बड़ी श्रेणी')}</span><h2>${catName(top[0].name)}</h2><strong>${money(top[0].value)}</strong><p>${L('August spending in your leading category.','अगस्त में सबसे बड़ी श्रेणी का खर्च।')}</p>${icon(top[0].icon)}</article><article class="story-card mint"><span>02 / ${L('THE STRONGEST CASH-FLOW MONTH','सबसे अच्छा नकदी प्रवाह महीना')}</span><h2>${tx(strongest.name)}</h2><strong>${money(strongest.surplus)}</strong><p>${strongest.complete?L(`${pct(strongest.surplus,strongest.income)}% of income before goal contributions.`,`${pct(strongest.surplus,strongest.income)}% आय, लक्ष्य योगदान से पहले।`):L('Partial cash-flow balance, not household savings.','आंशिक नकदी शेष, पूरे घर की बचत नहीं।')}</p>${icon('target')}</article><article class="story-card lilac"><span>03 / ${L('THE HIGHEST-SPEND MONTH','सबसे अधिक खर्च का महीना')}</span><h2>${tx(highest.name)}</h2><strong>${money(highest.out)}</strong><p>${L('Among the three available sample months.','उपलब्ध तीन नमूना महीनों में।')}</p>${icon('chart')}</article><article class="story-card sand"><span>04 / ${L('A PATTERN TO REVIEW','समीक्षा करने योग्य पैटर्न')}</span><h2>${L('Your subscription stack','आपकी सदस्यताएँ')}</h2><strong>${money(subs.reduce((s,t)=>s+t.amount,0))}</strong><p>${L(`${subs.length} August subscription-category records. Check which ones you still use.`,`${subs.length} अगस्त सदस्यता श्रेणी रिकॉर्ड। जाँचें कौन से अब भी उपयोग करते हैं।`)}</p>${icon('repeat')}</article></div><div class="grid2 gap"><section class="card"><h2>${L('Did your cash flow improve?','क्या आपका नकदी प्रवाह बेहतर हुआ?')}</h2><div class="comparison-cards">${[first,last].map(x=>`<div><span>${tx(x.name)} 2026</span><strong>${money(x.out)}</strong><small>${L('money out','खर्च')}</small>${percentBar(x.out,Math.max(first.out,last.out))}<b>${x.complete?pct(x.surplus,x.income)+'%':'—'} ${L('left after spending','खर्च के बाद बचा')}</b></div>`).join('')}</div><p class="muted gap">${L(`Spending ${change>=0?'rose':'fell'} by ${money(Math.abs(change))} (${pct(Math.abs(change),first.out)}%). Compare needs before deciding what to cut.`,`खर्च ${money(Math.abs(change))} (${pct(Math.abs(change),first.out)}%) ${change>=0?'बढ़ा':'घटा'}। कटौती से पहले ज़रूरतों की तुलना करें।`)}</p></section><section class="card"><h2>${L('Patterns SAARTHI noticed','सारथी ने ये पैटर्न देखे')}</h2><div class="history-columns">${list.map(x=>`<div><strong>${compact(x.out)}</strong><div class="history-track"><i style="height:${pct(x.out,highest.out)}%"></i></div><span>${tx(x.name)}</span></div>`).join('')}</div><p class="small muted">${L('The sample fixture scales expense records across three months. It cannot establish genuine seasonality, forgotten payments, duplicate benefits or fraud. Verify before cancelling anything.','नमूना डेटा तीन महीनों में खर्च को अनुपात से बदलता है। इससे मौसम, भूले भुगतान, दोहरे लाभ या धोखाधड़ी साबित नहीं होती। कुछ रद्द करने से पहले जाँचें।')}</p>${navTo(L('Review my spending','मेरा खर्च देखें'),'spending','text-btn')}</section></div>`;}
function rewardBalance(){extra();return state.rewardLedger.reduce((s,x)=>s+x.points,0)-state.redemptions.reduce((s,x)=>s+x.cost,0);}
function award(id,points,label){extra();if(state.rewardLedger.some(x=>x.id===id))return false;state.rewardLedger.push({id,points,label,date:new Date().toISOString()});save();return true;}
function rewardMissions(){const cats=categories('August').filter(x=>Number.isFinite(x.budget)&&x.value>0),met=cats.filter(x=>x.value<=x.budget).length;return [{id:'learn-buffer',title:L('Know your safety buffer','अपना सुरक्षा रिज़र्व समझें'),points:20,ready:true,kind:'learn'},{id:'review-budget',title:L('Review your monthly boundaries','अपने मासिक बजट की समीक्षा करें'),points:Math.max(10,Math.min(40,met*5)),ready:monthly('August').complete&&met>0,kind:'budget'},{id:'first-scenario',title:L('Understand one financial trade-off','एक वित्तीय विकल्प का असर समझें'),points:25,ready:state.simulations.length>0,kind:'scenario'},{id:'follow-through',title:L('Follow through on your checklist','अपनी सूची का एक कदम पूरा करें'),points:15,ready:Object.values(state.checks).some(x=>x.done),kind:'check'}];}
const REWARDS=[{id:'wellness',cost:30,icon:'heart',title:()=>L('A mindful pause','सुकून का एक पल'),desc:()=>L('Sample guided mindfulness session','नमूना निर्देशित माइंडफुलनेस सत्र')},{id:'fitness',cost:50,icon:'bolt',title:()=>L('Move a little more','थोड़ा और चलें'),desc:()=>L('Sample community fitness class','नमूना सामुदायिक फिटनेस कक्षा')},{id:'travel',cost:60,icon:'plane',title:()=>L('Your next adventure, planned','अगली यात्रा की तैयारी'),desc:()=>L('Sample destination-planning workshop','नमूना यात्रा योजना कार्यशाला')},{id:'food',cost:45,icon:'cup',title:()=>L('Something good at home','घर पर कुछ अच्छा'),desc:()=>L('Sample healthy-cooking masterclass','नमूना स्वस्थ खाना बनाने की कक्षा')}];
function rewards(){const missions=rewardMissions(),travel=state.goals.some(g=>g.icon==='plane'),offers=REWARDS.slice().sort((a,b)=>(b.id==='travel'&&travel?1:0)-(a.id==='travel'&&travel?1:0));return `${head(L('SMALL HABITS, RECOGNISED','छोटी आदतों की पहचान'),L('Progress deserves<br>a little celebration.','प्रगति का<br>थोड़ा जश्न हो जाए।'),L('Earn for learning and following through—not for spending or sharing more data.','सीखने और कदम पूरा करने पर कमाएँ—खर्च करने या अधिक डेटा देने पर नहीं।'))}<section class="points-hero"><div><span class="eyebrow">SAARTHI POINTS</span><strong>${rewardBalance()}<small>${L('points available','पॉइंट्स उपलब्ध')}</small></strong><p>${L('A little momentum for your money journey.','आपकी वित्तीय यात्रा के लिए थोड़ा उत्साह।')}</p></div><div class="points-emblem" aria-hidden="true">${icon('gem')}</div></section><div class="section-title gap"><h2>${L('Your healthy-money missions','आपकी अच्छी वित्तीय आदतों के मिशन')}</h2></div><div class="grid2">${missions.map(m=>{const claimed=state.rewardLedger.some(x=>x.id===m.id);return `<article class="mission-card"><span class="symbol">${icon(claimed?'check':'target')}</span><div><h3>${m.title}</h3><p>${m.points} ${L('points · one-time milestone','पॉइंट्स · एक बार का पड़ाव')}</p></div>${button(claimed?L('Earned','कमाए'):m.kind==='learn'?L('Learn','सीखें'):m.ready?L('Claim','प्राप्त करें'):L('Explore','देखें'),'mission','btn sm',`data-id="${m.id}" ${claimed?'disabled':''}`)}</article>`;}).join('')}</div><div class="section-title gap"><div><h2>${L('A few benefits for you','आपके लिए कुछ लाभ')}</h2><p>${travel?L('Travel appears first because you have a travel goal.','आपका यात्रा लक्ष्य है, इसलिए यात्रा पहले दिखाई गई है।'):L('Explore wellbeing and learning experiences.','स्वास्थ्य और सीखने के अनुभव देखें।')}</p></div></div><div class="grid2">${offers.map((r,i)=>`<article class="reward-card"><div class="reward-art art-${i}">${icon(r.icon)}<span>${L('DEMO BENEFIT','डेमो लाभ')}</span></div><div><h3>${r.title()}</h3><p>${r.desc()}</p><div class="between"><b>${r.cost} ${L('points','पॉइंट्स')}</b>${button(state.redemptions.some(x=>x.id===r.id)?L('View pass','पास देखें'):L('View benefit','लाभ देखें'),'reward-detail','btn sm',`data-id="${r.id}"`)}</div></div></article>`).join('')}</div><p class="small muted gap">${L('All partners and benefits are fictional. Points have no cash value; no purchases, external registrations or real vouchers are involved. One claim per milestone and one redemption per benefit.','सभी साझेदार और लाभ काल्पनिक हैं। पॉइंट्स का नकद मूल्य नहीं; कोई खरीदारी, बाहरी पंजीकरण या असली वाउचर नहीं। हर पड़ाव और लाभ एक बार ही मिलेगा।')}</p><details class="card gap"><summary>${L('Points activity','पॉइंट्स गतिविधि')}</summary>${state.rewardLedger.map(x=>`<div class="between task-row"><span>${esc(x.label)}</span><b>+${x.points}</b></div>`).join('')}${state.redemptions.map(x=>`<div class="between task-row"><span>${REWARDS.find(r=>r.id===x.id)?.title()||esc(x.id)}</span><b>−${x.cost}</b></div>`).join('')||''}</details>`;}
function rewardDetail(id){const r=REWARDS.find(x=>x.id===id);if(!r)return;const claimed=state.redemptions.find(x=>x.id===id);modal(r.title(),`<div class="reward-art art-1">${icon(r.icon)}</div><p class="lead">${r.desc()}</p>${claimed?`<div class="sample-pass"><span>${L('YOUR SAMPLE PASS','आपका नमूना पास')}</span><strong>SAARTHI-${esc(id.toUpperCase())}-DEMO</strong><p>${L('Presentation only. Not redeemable with a real partner.','सिर्फ़ प्रस्तुति के लिए। असली साझेदार से उपयोग नहीं हो सकता।')}</p></div>`:`<p>${L('Use','उपयोग करें')} <b>${r.cost} ${L('points','पॉइंट्स')}</b>. ${L('Available:','उपलब्ध:')} ${rewardBalance()}.</p><p class="small muted">${L('This creates a local sample pass only. No partner receives your data.','यह सिर्फ़ स्थानीय नमूना पास बनाता है। किसी साझेदार को डेटा नहीं मिलता।')}</p>${button(rewardBalance()>=r.cost?L('Confirm sample redemption','नमूना रिडेम्पशन की पुष्टि करें'):L('Earn more points first','पहले और पॉइंट्स कमाएँ'),'redeem-reward','btn primary',`data-id="${id}" ${rewardBalance()<r.cost?'disabled':''}`)}`}`);}
const baseReportDownload=reportDownload;
reportBody=function(){const f=fitnessValue(),body=originalReportBody();const summary=`<section class="report-fitness"><div class="section-title"><div><span class="eyebrow">${L('FINANCIAL FITNESS REPORT','वित्तीय सेहत रिपोर्ट')}</span><h2>${L('Start with the whole picture.','पूरी तस्वीर से शुरुआत करें।')}</h2><p>${L(`${f.count}/5 pillars assessed; equal average of assessable indicators.`,`${f.count}/5 स्तंभ जाँचे; जाँचे जा सकने वाले संकेतकों का समान औसत।`)}</p></div>${scoreRing(f.score,true)}</div><div class="report-pillar-list">${f.pillars.map(p=>`<div><b>${labelP(p.id)} · ${p.score??'—'} / 100</b><p>${p.desc}</p></div>`).join('')}</div><p class="small muted">${L('A demo coaching index, not a credit or suitability score. Protection and taxes measure confirmed checklist readiness, not adequacy or tax efficiency. Monthly score comparisons hold non-spending data constant.','डेमो कोचिंग संकेतक, क्रेडिट या उपयुक्तता स्कोर नहीं। सुरक्षा और कर पुष्ट तैयारी मापते हैं, पर्याप्तता या कर दक्षता नहीं। मासिक तुलना में गैर-खर्च डेटा स्थिर रहता है।')}</p></section>`;return summary+body;};
reportDownload=function(){const content=reportBody();download('Arjun_SAARTHI_Financial_Health.html',`<!doctype html><html lang="${preferences.language}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SAARTHI · Financial health report</title><style>body{font:16px/1.6 Arial,sans-serif;max-width:960px;margin:auto;padding:24px;color:#28232b}h1,h2,h3,b,.brand{color:#97144d}.brand small{display:block}.icon,button{display:none}table{width:100%;border-collapse:collapse}th,td{padding:12px;text-align:left;border-bottom:1px solid #ddd}.table-wrap{overflow:auto}.fitness-ring{font-size:40px;font-weight:700}.fitness-ring span{font-size:14px;margin-left:8px}.report-pillar-list{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.report-pillar-list>div,.report-stats>div{background:#f8eef3;padding:16px;border-radius:12px}.report-stats{display:flex;gap:12px}.report-stats strong{display:block;font-size:24px}.small{font-size:13px}.muted{color:#6c626c}.report-fitness{border-bottom:2px solid #97144d;padding-bottom:20px;margin-bottom:28px}@media(max-width:600px){.report-pillar-list{grid-template-columns:1fr}.report-stats{display:block}}@media print{body{padding:0}.report-pillar-list>div{break-inside:avoid}}</style></head><body>${content}</body></html>`,'text/html;charset=utf-8');toast(L('Your report is downloaded.','आपकी रिपोर्ट डाउनलोड हो गई।'));};
askReply=function(q){const low=q.toLowerCase(),f=fitnessValue();if(/score|fitness|सेहत|स्कोर/.test(low))return L(`Your demo fitness score is ${f.score??'not assessed'}, with ${f.count} of 5 pillars assessed. ${f.pillars.filter(p=>p.score!==null).map(p=>labelP(p.id)+': '+p.score).join('; ')}. Open Fitness to see the methodology and missing context.`,`आपका डेमो सेहत स्कोर ${f.score??'अभी अज्ञात'} है; ${f.count} में से 5 स्तंभ जाँचे हैं। ${f.pillars.filter(p=>p.score!==null).map(p=>labelP(p.id)+': '+p.score).join('; ')}। तरीके और अधूरी जानकारी के लिए वित्तीय सेहत खोलें।`);if(/reward|point|रिवॉर्ड|पॉइंट/.test(low))return L(`You have ${rewardBalance()} SAARTHI Points. Learn about reserves, review budgets, save a scenario or complete a checklist action. Benefits are fictional; you never need to spend or share more data to earn learning points.`,`आपके पास ${rewardBalance()} सारथी पॉइंट्स हैं। रिज़र्व सीखें, बजट देखें, परिदृश्य सहेजें या सूची का कदम पूरा करें। लाभ काल्पनिक हैं; सीखने के अंक के लिए खर्च या अधिक डेटा देना ज़रूरी नहीं।`);if(/tax|कर|टैक्स/.test(low))return L(`Your tax regime is ${state.health.regime}; ${state.health.docs.length}/4 preparation documents are confirmed. I cannot estimate tax savings without verified facts and applicable rules. Use Fitness → Taxes to prepare for a qualified review.`,`आपकी कर व्यवस्था ${state.health.regime} है; ${state.health.docs.length}/4 तैयारी दस्तावेज़ पुष्ट हैं। सत्यापित तथ्य और नियम बिना कर बचत नहीं गिनी जा सकती। वित्तीय सेहत → कर में समीक्षा की तैयारी करें।`);if(preferences.language==='hi'){if(/खर्च|बजट|आय|बचत/.test(low)){const c=cash();return c.available?`चुने ${tx(month)} लेन-देन में आय ${money(c.income)}, खर्च ${money(c.out)} और शेष ${money(c.surplus)} है। ${c.complete?'EMI पहले से खर्च में शामिल है।':'यह आंशिक तस्वीर है।'} खर्च में अपने बजट बदल सकते हैं।`:'खर्च समझने के लिए बैंक खाता और लेन-देन की अनुमति चुनें।';}if(/लक्ष्य|घर/.test(low))return 'लक्ष्य में अपनी बची राशि, मासिक योगदान और समय देखें। परिदृश्य में एक बदलाव का असर आज़माएँ। कोई पैसा अपने आप नहीं भेजा जाता।';if(/डेटा|अनुमति/.test(low))return `आपने ${state.selected.length} नमूना खाते चुने हैं। डेटा इसी ब्राउज़र में रहता है। डेटा और गोपनीयता में अनुमति वापस लें।`;if(/बीमा|सुरक्षा/.test(low))return hasType('insurance')?'नियोक्ता का ₹5 लाख नमूना स्वास्थ्य कवर दिखता है। निजी पॉलिसी और ज़रूरतें पुष्टि के बिना पर्याप्तता तय नहीं होती।':'बीमा जानकारी साझा नहीं है। कवर का निष्कर्ष नहीं निकाला जा सकता।';return `मैं आपके नमूना डेटा, खर्च, लक्ष्यों, स्कोर और अनुमतियों को समझने में मदद कर सकता हूँ। उपलब्ध शुद्ध संपत्ति ${money(totals().net)} है। यह संदर्भ आधारित नियमों का डेमो है, लाइव AI या व्यक्तिगत निवेश सलाह नहीं।`;}
 return originalAsk(q);
};
chat=function(){const c=cash();if(!chatHistory.length)chatHistory=[{role:'assistant',text:L(`Hi Arjun. I’m SAARTHI, your personal CFO. Let’s turn your financial picture into a useful next step. ${c.complete?'Your current sample cash-flow balance is '+money(c.surplus)+', before goal contributions.':'You control which sample accounts I can see.'}`,`नमस्ते अर्जुन। मैं सारथी, आपका निजी CFO हूँ। आपकी वित्तीय तस्वीर से अगला उपयोगी कदम समझते हैं। ${c.complete?'लक्ष्य योगदान से पहले नमूना नकदी शेष '+money(c.surplus)+' है।':'आप तय करते हैं कि कौन से नमूना खाते मैं देख सकता हूँ।'}`)}];modal(L('SAARTHI AI · Your personal CFO','सारथी AI · आपका निजी CFO'),`<div class="chat-context"><span class="symbol">${icon('spark')}</span><div><b>${L('Already in context. Always in your control.','जानकारी जुड़ी है। नियंत्रण आपका है।')}</b><small>${L(`${state.selected.length} selected sample accounts · contextual rules, not live AI`,`${state.selected.length} चुने नमूना खाते · संदर्भ आधारित नियम, लाइव AI नहीं`)}</small></div></div><div class="suggestions gap">${[[L('How is my fitness?','मेरा सेहत स्कोर?')],[L('My monthly surplus','मेरी मासिक बचत')],[L('My goals','मेरे लक्ष्य')],[L('My rewards','मेरे रिवॉर्ड्स')]].map(([q])=>button(q,'chat-suggest','btn sm',`data-value="${q}"`)).join('')}</div><div id="chat-stream" class="chat-stream" role="log" aria-live="polite">${chatHistory.map(m=>`<div class="bubble ${m.role==='user'?'user':''}">${esc(m.text)}</div>`).join('')}</div><div class="chat-destinations">${button(L('Explore fitness','सेहत देखें'),'detail-nav','text-btn','data-page="fitness"')}${button(L('Try a what-if','परिदृश्य आज़माएँ'),'detail-nav','text-btn','data-page="scenarios"')}${button(L('Review investments','निवेश देखें'),'detail-nav','text-btn','data-page="investments"')}</div><form id="chat-form" class="chat-form"><input name="question" aria-label="${L('Your question','आपका प्रश्न')}" placeholder="${L('What would you like to understand?','आप क्या समझना चाहेंगे?')}" maxlength="300" required autocomplete="off"><button class="btn primary" type="submit" aria-label="${L('Send question','प्रश्न भेजें')}">${icon('arrow')}</button></form>`);const stream=document.getElementById('chat-stream');stream.scrollTop=stream.scrollHeight;};
// Capture preference changes before the original handlers rerender onboarding.
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(['theme','device'].includes(b.dataset.action)&&step===1&&(!state.onboarded||editConsent)){draftTx=document.getElementById('transaction-consent').checked;draftDuration=Number(document.getElementById('duration').value);draftFrequency=document.getElementById('frequency').value;}},true);
document.addEventListener('change',e=>{if(e.target.id==='language-select'){chatHistory=[];if(step===1&&(!state.onboarded||editConsent)){draftTx=document.getElementById('transaction-consent').checked;draftDuration=Number(document.getElementById('duration').value);draftFrequency=document.getElementById('frequency').value;}}},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;extra();const id=b.dataset.id,a=b.dataset.action;
 if(a==='pillar')pillarDetail(id);
 if(a==='health-profile')healthProfile();
 if(a==='method')modal(L('A transparent demo score','एक पारदर्शी डेमो स्कोर'),`<p>${L('The overall score is the equally weighted average of assessable pillars. Missing inputs exclude a pillar; the coverage count stays visible. This is not a validated financial-health model.','कुल स्कोर जाँचे जा सकने वाले स्तंभों का समान औसत है। अधूरी जानकारी वाला स्तंभ बाहर रहता है; कवरेज दिखाई जाती है। यह सत्यापित वित्तीय सेहत मॉडल नहीं है।')}</p>${profilePillars().map(p=>`<h3>${labelP(p.id)}</h3><p>${p.formula}</p>`).join('')}`);
 if(a==='add-check'){const i=coachData().find(x=>x.id===id);if(i){state.checks[id]??={title:i.title,done:false};save();toast(L('Added to your insight checklist.','आपकी जानकारी सूची में जोड़ा गया।'));}}
 if(a==='check-done'&&state.checks[id]){state.checks[id].done=!state.checks[id].done;save();render();}
 if(a==='target-new')targetDialog();if(a==='target-edit')targetDialog(id);
 if(a==='target-remove'){if(CATEGORIES.some(x=>x[0]===id))state.budgets[id]=null;else delete state.customBudgets[id];save();dialog.close();render();toast(L('Target removed. Transactions are unchanged.','लक्ष्य हटाया। लेन-देन नहीं बदले।'));}
 if(a==='asset-route'){investFilter=id;render();document.getElementById('invest-filter')?.scrollIntoView({behavior:'smooth',block:'center'});}
 if(a==='scenario-preset'&&SCENARIOS[id]){scenarioType=id;scenarioValue=SCENARIOS[id].value;page='scenarios';dialog.close();render();window.scrollTo(0,0);}
 if(a==='store-simulation'){const r=scenarioResult(scenarioType,scenarioValue);if(r.available){state.simulations.push({id:'sim-'+Date.now(),type:scenarioType,value:scenarioValue,label:SCENARIOS[scenarioType].label()+' · '+(scenarioType==='market'?scenarioValue+'%':money(scenarioValue))});state.simulations=state.simulations.slice(-12);save();render();toast(L('Scenario saved. No plan or payment changed.','परिदृश्य सहेजा। योजना या भुगतान नहीं बदले।'));}}
 if(a==='load-simulation'){const s=state.simulations.find(x=>x.id===id);if(s){scenarioType=s.type;scenarioValue=s.value;render();window.scrollTo(0,0);}}
 if(a==='delete-simulation'){state.simulations=state.simulations.filter(x=>x.id!==id);save();render();}
 if(a==='mission'){const m=rewardMissions().find(x=>x.id===id);if(!m||state.rewardLedger.some(x=>x.id===id))return;if(m.kind==='learn')modal(L('A buffer buys breathing room','रिज़र्व राहत देता है'),`<p>${L('Emergency money should be accessible and not already earmarked for other goals. Your chosen target depends on your needs—not a universal number. Restricted retirement assets are not readily available cash.','आपातकालीन पैसा सुलभ होना चाहिए और दूसरे लक्ष्य के लिए तय नहीं होना चाहिए। लक्ष्य आपकी ज़रूरत पर निर्भर है—सार्वभौमिक संख्या नहीं। प्रतिबंधित रिटायरमेंट संपत्ति तुरंत उपलब्ध नकद नहीं है।')}</p><h3>${L('Which should you check first?','पहले क्या जाँचना चाहिए?')}</h3>${button(L('Whether the money is actually available','क्या पैसा वास्तव में उपलब्ध है'),'learn-answer','btn primary','data-id="correct"')}${button(L('Which reward offers the biggest discount','किस रिवॉर्ड में सबसे बड़ी छूट है'),'learn-answer','btn gap','data-id="wrong"')}`);else if(m.ready){award(m.id,m.points,m.title);render();toast(L('Milestone recognised. Points added.','पड़ाव की पहचान हुई। पॉइंट्स जोड़े गए।'));}else {page=m.kind==='scenario'?'scenarios':m.kind==='budget'?'spending':'insights';render();}}
 if(a==='learn-answer'){if(id==='correct'){award('learn-buffer',20,L('Know your safety buffer','अपना सुरक्षा रिज़र्व समझें'));dialog.close();render();toast(L('Exactly. 20 learning points earned once.','बिल्कुल। सीखने के 20 पॉइंट्स एक बार मिले।'));}else toast(L('Think about access and earmarks before rewards. Try again.','रिवॉर्ड से पहले उपलब्धता और तय उपयोग सोचें। फिर कोशिश करें।'));}
 if(a==='reward-detail')rewardDetail(id);
 if(a==='redeem-reward'){const r=REWARDS.find(x=>x.id===id);if(r&&rewardBalance()>=r.cost&&!state.redemptions.some(x=>x.id===id)){state.redemptions.push({id,cost:r.cost,date:new Date().toISOString()});save();render();rewardDetail(id);}}
 // Revoking account access removes stale chat answers from the current session.
 if(['confirm-revoke','confirm-revoke-all','finish-consent','confirm-reset'].includes(a))chatHistory=[];
});
document.addEventListener('input',e=>{if(e.target.id==='whatif-range'){scenarioValue=clamp(Number(e.target.value),0,SCENARIOS[scenarioType].max);document.getElementById('whatif-value').textContent=scenarioType==='market'?scenarioValue+'%':money(scenarioValue);document.getElementById('whatif-output').innerHTML=scenarioOutput();}});
document.addEventListener('submit',e=>{const form=e.target;if(!['health-form','target-form'].includes(form.id))return;e.preventDefault();extra();const d=new FormData(form);if(form.id==='health-form'){const dependants=Number(d.get('dependants')),personalHealth=Number(d.get('personalHealth')),life=Number(d.get('life'));if(!Number.isInteger(dependants)||dependants<0||dependants>20||![personalHealth,life].every(n=>Number.isFinite(n)&&n>=0)||!d.get('confirm'))return;state.health={confirmed:true,dependants,personalHealth,life,regime:d.get('regime'),docs:d.getAll('docs').filter(x=>['income','interest','gains','tax'].includes(x))};}else {const name=String(d.get('category')).trim(),amount=Number(d.get('amount'));if(!name||['__proto__','constructor','prototype'].includes(name)||!Number.isFinite(amount)||amount<0||amount>10000000){document.getElementById('target-error').textContent=L('Enter a valid category and amount.','सही श्रेणी और राशि भरें।');return;}if(CATEGORIES.some(x=>x[0]===name))state.budgets[name]=amount;else state.customBudgets[name]=amount;}save();dialog.close();render();toast(L('Saved. Your insights have been recalculated.','सहेजा गया। जानकारियाँ दोबारा गिनी गईं।'));});
render();
